package main

import "core:bytes"
import "core:net"
import "core:strconv"
import "core:strings"

MAX_HEADER_BYTES :: 64 * 1024
MAX_BODY_BYTES :: 1024 * 1024
// Oversized bodies are read and discarded up to this many bytes so that the
// client receives the error response instead of a connection reset.
MAX_DRAIN_BYTES :: 64 * 1024 * 1024

Request :: struct {
	method: string,
	path:   string,
	body:   []byte,
}

Status :: enum {
	OK                    = 200,
	Created               = 201,
	No_Content            = 204,
	Bad_Request           = 400,
	Not_Found             = 404,
	Method_Not_Allowed    = 405,
	Content_Too_Large     = 413,
	Header_Too_Large      = 431,
	Internal_Server_Error = 500,
	Not_Implemented       = 501,
}

status_text :: proc(s: Status) -> string {
	switch s {
	case .OK:                    return "OK"
	case .Created:               return "Created"
	case .No_Content:            return "No Content"
	case .Bad_Request:           return "Bad Request"
	case .Not_Found:             return "Not Found"
	case .Method_Not_Allowed:    return "Method Not Allowed"
	case .Content_Too_Large:     return "Content Too Large"
	case .Header_Too_Large:      return "Request Header Fields Too Large"
	case .Internal_Server_Error: return "Internal Server Error"
	case .Not_Implemented:       return "Not Implemented"
	}
	return "Unknown"
}

Response :: struct {
	status:       Status,
	content_type: string,
	allow:        string,
	body:         []byte,
}

Read_Error :: enum {
	None,
	Closed,         // peer closed or socket error before a full request arrived
	Malformed,      // syntactically invalid request
	Header_Too_Large,
	Body_Too_Large,
	Unsupported,    // e.g. Transfer-Encoding
}

// read_request reads one HTTP/1.1 request from the socket. All memory comes
// from context.allocator; strings in the returned Request view that memory.
read_request :: proc(sock: net.TCP_Socket) -> (req: Request, err: Read_Error) {
	buf := make([dynamic]byte, 0, 4096)
	chunk: [4096]byte

	header_end := -1
	for header_end < 0 {
		n, rerr := net.recv_tcp(sock, chunk[:])
		if rerr != nil || n == 0 {
			return {}, .Closed
		}
		// Only rescan the region that could contain a new terminator.
		scan_from := max(0, len(buf) - 3)
		append(&buf, ..chunk[:n])
		if i := bytes.index(buf[scan_from:], {'\r', '\n', '\r', '\n'}); i >= 0 {
			header_end = scan_from + i
		} else if len(buf) > MAX_HEADER_BYTES {
			return {}, .Header_Too_Large
		}
	}
	if header_end > MAX_HEADER_BYTES {
		return {}, .Header_Too_Large
	}

	head := string(buf[:header_end])
	request_line, _ := strings.split_iterator(&head, "\r\n")
	parts := request_line
	method, _ := strings.split_iterator(&parts, " ")
	target, _ := strings.split_iterator(&parts, " ")
	version := parts
	if method == "" || target == "" || !strings.has_prefix(version, "HTTP/1.") {
		return {}, .Malformed
	}
	req.method = method
	req.path = target

	content_length := 0
	for line in strings.split_iterator(&head, "\r\n") {
		colon := strings.index_byte(line, ':')
		if colon <= 0 {
			return {}, .Malformed
		}
		name := line[:colon]
		value := strings.trim_space(line[colon + 1:])
		switch {
		case strings.equal_fold(name, "Content-Length"):
			cl, ok := strconv.parse_int(value, 10)
			if !ok || cl < 0 {
				return {}, .Malformed
			}
			content_length = cl
		case strings.equal_fold(name, "Transfer-Encoding"):
			return {}, .Unsupported
		}
	}

	body_start := header_end + 4
	if content_length > MAX_BODY_BYTES {
		drain(sock, content_length - (len(buf) - body_start))
		return req, .Body_Too_Large
	}

	body := make([]byte, content_length)
	have := copy(body, buf[body_start:])
	for have < content_length {
		n, rerr := net.recv_tcp(sock, body[have:])
		if rerr != nil || n == 0 {
			return {}, .Closed
		}
		have += n
	}
	req.body = body
	return req, .None
}

// drain reads and discards up to `remaining` bytes (bounded by MAX_DRAIN_BYTES).
@(private = "file")
drain :: proc(sock: net.TCP_Socket, count: int) {
	remaining := min(count, MAX_DRAIN_BYTES)
	scratch: [16 * 1024]byte
	for remaining > 0 {
		n, err := net.recv_tcp(sock, scratch[:min(remaining, len(scratch))])
		if err != nil || n == 0 {
			return
		}
		remaining -= n
	}
}

write_response :: proc(sock: net.TCP_Socket, res: Response) -> net.TCP_Send_Error {
	b := strings.builder_make(0, 256)
	defer strings.builder_destroy(&b)

	code := int(res.status)
	strings.write_string(&b, "HTTP/1.1 ")
	strings.write_int(&b, code)
	strings.write_byte(&b, ' ')
	strings.write_string(&b, status_text(res.status))
	strings.write_string(&b, "\r\nContent-Length: ")
	strings.write_int(&b, len(res.body))
	strings.write_string(&b, "\r\nConnection: close\r\n")
	if res.content_type != "" {
		strings.write_string(&b, "Content-Type: ")
		strings.write_string(&b, res.content_type)
		strings.write_string(&b, "\r\n")
	}
	if res.allow != "" {
		strings.write_string(&b, "Allow: ")
		strings.write_string(&b, res.allow)
		strings.write_string(&b, "\r\n")
	}
	strings.write_string(&b, "\r\n")

	// Small bodies go out in the same write as the header.
	if len(res.body) <= 16 * 1024 {
		strings.write_bytes(&b, res.body)
		_, err := net.send_tcp(sock, b.buf[:])
		return err
	}
	net.send_tcp(sock, b.buf[:]) or_return
	_, err := net.send_tcp(sock, res.body)
	return err
}

package main

import "core:fmt"
import vmem "core:mem/virtual"
import "core:net"
import "core:os"
import "core:strconv"
import "core:sys/posix"
import "core:thread"
import "core:time"

IO_TIMEOUT :: 30 * time.Second

Connection :: struct {
	sock:  net.TCP_Socket,
	store: ^Store,
}

main :: proc() {
	if len(os.args) != 2 {
		fmt.eprintfln("usage: %s <port>", os.args[0])
		os.exit(2)
	}
	port, ok := strconv.parse_int(os.args[1], 10)
	if !ok || port < 1 || port > 65535 {
		fmt.eprintfln("invalid port: %q", os.args[1])
		os.exit(2)
	}

	// Writes to a peer that has gone away must not kill the process.
	posix.signal(.SIGPIPE, auto_cast posix.SIG_IGN)

	store: Store
	store_init(&store)
	defer store_destroy(&store)

	endpoint := net.Endpoint{address = net.IP4_Loopback, port = port}
	listener, err := net.listen_tcp(endpoint, 1024)
	if err != nil {
		fmt.eprintfln("listen on %v failed: %v", net.endpoint_to_string(endpoint, context.temp_allocator), err)
		os.exit(1)
	}
	defer net.close(listener)

	for {
		sock, _, aerr := net.accept_tcp(listener)
		if aerr != nil {
			continue
		}
		conn := new(Connection)
		conn^ = {sock = sock, store = &store}
		thread.create_and_start_with_poly_data(conn, serve_connection, self_cleanup = true)
	}
}

// serve_connection handles a single request and closes the connection.
serve_connection :: proc(conn: ^Connection) {
	sock, store := conn.sock, conn.store
	free(conn)
	defer net.close(sock)

	net.set_option(sock, .Receive_Timeout, IO_TIMEOUT)
	net.set_option(sock, .Send_Timeout, IO_TIMEOUT)

	// Every allocation for this request lives in one arena, freed at once.
	arena: vmem.Arena
	if vmem.arena_init_growing(&arena) != nil {
		return
	}
	defer vmem.arena_destroy(&arena)
	context.allocator = vmem.arena_allocator(&arena)

	res: Response
	req, rerr := read_request(sock)
	switch rerr {
	case .None:             res = handle(store, req)
	case .Closed:           return
	case .Malformed:        res = {status = .Bad_Request}
	case .Header_Too_Large: res = {status = .Header_Too_Large}
	case .Body_Too_Large:   res = {status = .Content_Too_Large}
	case .Unsupported:      res = {status = .Not_Implemented}
	}

	if write_response(sock, res) == nil {
		net.shutdown(sock, .Send)
	}
}

package main

import "core:strings"

KV_PREFIX :: "/kv/"
MAX_KEY_LEN :: 64

is_valid_key :: proc(key: string) -> bool {
	if len(key) == 0 || len(key) > MAX_KEY_LEN {
		return false
	}
	for i in 0 ..< len(key) {
		switch key[i] {
		case 'A' ..= 'Z', 'a' ..= 'z', '0' ..= '9', '_', '-':
		case:
			return false
		}
	}
	return true
}

text :: proc(status: Status, body := "") -> Response {
	return {status = status, content_type = "text/plain; charset=utf-8" if body != "" else "", body = transmute([]byte)body}
}

method_not_allowed :: proc(allow: string) -> Response {
	return {status = .Method_Not_Allowed, allow = allow}
}

// handle maps a request to a response. Response memory comes from context.allocator.
handle :: proc(store: ^Store, req: Request) -> Response {
	switch {
	case req.path == "/health":
		if req.method != "GET" {
			return method_not_allowed("GET")
		}
		return text(.OK, "ok")

	case req.path == "/kv":
		if req.method != "GET" {
			return method_not_allowed("GET")
		}
		return list_keys(store)

	case strings.has_prefix(req.path, KV_PREFIX):
		key := req.path[len(KV_PREFIX):]
		if !is_valid_key(key) {
			return {status = .Bad_Request}
		}
		switch req.method {
		case "GET":
			value, found := store_get(store, key)
			if !found {
				return {status = .Not_Found}
			}
			return {status = .OK, content_type = "application/octet-stream", body = value}
		case "PUT":
			created := store_put(store, key, req.body)
			return {status = .Created if created else .OK}
		case "DELETE":
			if !store_delete(store, key) {
				return {status = .Not_Found}
			}
			return {status = .No_Content}
		case:
			return method_not_allowed("GET, PUT, DELETE")
		}
	}
	return {status = .Not_Found}
}

list_keys :: proc(store: ^Store) -> Response {
	keys := store_keys(store)

	// Keys are restricted to [A-Za-z0-9_-], so no JSON escaping is needed.
	b := strings.builder_make()
	strings.write_byte(&b, '[')
	for k, i in keys {
		if i > 0 {
			strings.write_byte(&b, ',')
		}
		strings.write_byte(&b, '"')
		strings.write_string(&b, k)
		strings.write_byte(&b, '"')
	}
	strings.write_byte(&b, ']')
	return {status = .OK, content_type = "application/json", body = b.buf[:]}
}

package main

import "core:slice"
import "core:strings"
import "core:sync"

// Store is a thread-safe in-memory map from key to value bytes.
// Keys and values are owned by the store's allocator.
Store :: struct {
	mu:        sync.RW_Mutex,
	entries:   map[string][]byte,
}

store_init :: proc(s: ^Store, allocator := context.allocator) {
	s.entries = make(map[string][]byte, allocator)
}

store_destroy :: proc(s: ^Store) {
	for k, v in s.entries {
		delete(k, s.entries.allocator)
		delete(v, s.entries.allocator)
	}
	delete(s.entries)
}

// store_put stores a copy of value under key. Returns true if the key was new.
store_put :: proc(s: ^Store, key: string, value: []byte) -> (created: bool) {
	alloc := s.entries.allocator
	val := slice.clone(value, alloc)

	sync.rw_mutex_lock(&s.mu)
	defer sync.rw_mutex_unlock(&s.mu)

	if old, ok := &s.entries[key]; ok {
		delete(old^, alloc)
		old^ = val
		return false
	}
	s.entries[strings.clone(key, alloc)] = val
	return true
}

// store_get returns a copy of the value for key, allocated with `allocator`.
store_get :: proc(s: ^Store, key: string, allocator := context.allocator) -> (value: []byte, found: bool) {
	sync.rw_mutex_shared_lock(&s.mu)
	defer sync.rw_mutex_shared_unlock(&s.mu)

	v := s.entries[key] or_return
	return slice.clone(v, allocator), true
}

store_delete :: proc(s: ^Store, key: string) -> (deleted: bool) {
	sync.rw_mutex_lock(&s.mu)
	defer sync.rw_mutex_unlock(&s.mu)

	k, v := delete_key(&s.entries, key)
	if k == "" {
		return false
	}
	delete(k, s.entries.allocator)
	delete(v, s.entries.allocator)
	return true
}

// store_keys returns all keys sorted ascending. Keys are copies owned by `allocator`.
store_keys :: proc(s: ^Store, allocator := context.allocator) -> []string {
	keys: [dynamic]string
	{
		sync.rw_mutex_shared_lock(&s.mu)
		defer sync.rw_mutex_shared_unlock(&s.mu)

		keys = make([dynamic]string, 0, len(s.entries), allocator)
		for k in s.entries {
			append(&keys, strings.clone(k, allocator))
		}
	}
	slice.sort(keys[:])
	return keys[:]
}
